var machine = getMachine((await listMachines())[0].id)
await machine.waitAndAcquire()
var page = await machine.browser.newtab("https://manicule-agent-benchmark-oct17.peppyshark33.chatgpt.site/?task=popup")
await wait({ waitTime: 2 })
var snap = await page.snapshot()
console.log(snap.snapshot.outline())

// Click the dropdown to open options
await page.select({ ref: "e16", values: ["Standard review"] })
await wait({ waitTime: 1 })
var snap = await page.snapshot()
console.log(snap.snapshot.outline())

// Try clicking the dropdown input again to see options, then pick Standard review
await page.click({ ref: "e16" })
await wait({ waitTime: 0.5 })
// Now try clicking the Standard review option
await page.click({ ref: "e15" })
await wait({ waitTime: 0.5 })
var snap = await page.snapshot()
console.log(snap.snapshot.outline())

// First open the dropdown
await page.click({ ref: "e16" })
await wait({ waitTime: 0.5 })
// Now click on the Standard review option
var snap2 = await page.snapshot()
console.log(snap2.snapshot.outline())
// Try clicking opt: Standard review
await page.click({ ref: "e15" })
await wait({ waitTime: 0.5 })
var snap3 = await page.snapshot()
console.log(snap3.snapshot.outline())

// Try using page.select on the dropdown input with values
await page.select({ ref: "e16", values: ["Standard review"] })
await wait({ waitTime: 0.5 })
var snap = await page.snapshot()
console.log(snap.snapshot.outline())

// Use evaluate to select the option
await page.evaluate({ ref: "e16", fn: "(el) => { el.value = 'Standard review'; el.dispatchEvent(new Event('change', { bubbles: true })); }" })
await wait({ waitTime: 0.5 })
var snap = await page.snapshot()
console.log(snap.snapshot.outline())
